def _rsi_trial_kv_cache_dtype(view: Any) -> dict:
    if view.kv_cache_dtype == 'bfloat16':
        if os.environ.get('SGLANG_SPARK_FP8_KV', '0') == '1':
            logger.warning('RSI trial-2: remapping kv_cache_dtype bfloat16 -> fp8_e4m3 (SGLANG_SPARK_FP8_KV=1).')
            return {'kv_cache_dtype': 'fp8_e4m3'}
        logger.info('RSI trial-2 fp8-KV remap inactive (SGLANG_SPARK_FP8_KV unset/0); exact-BF16 candidate.')
    return {}
